// ---- arimo.js ----

// GENERATED: Arimo Bold (SIL OFL 1.1) instanced at wght=700 and subset to Latin-1 plus the degree sign with
// fontTools. Arimo is metric-compatible with Arial, so the badge matches the original badge.py (Arial Bold)
// look exactly. Source: github.com/google/fonts ofl/arimo. Decoded once and parsed with opentype.js.

export const ARIMO_BOLD_BASE64 =
  "";

export function arimoBoldBytes() {
  const binary = atob(ARIMO_BOLD_BASE64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes.buffer;
}

// ---- meshNormals.js ----

// Normals for the preview.
//
// A solid that came out of a boolean is covered in triangles of wildly different sizes, and shading each by its
// own face leaves the walls striped. Averaging every triangle meeting at a point would instead round off the
// corners that ought to be sharp. So a point's normal is the average of the faces around it weighted by the angle
// each one turns through, and only of the faces within the crease angle — the flat top stays flat, the wall stays
// a wall, and the edge between them stays an edge.
//

export function creasedGeometry(vertices, triangles, creaseDegrees = 55) {
  const faces = triangles.length / 3;
  const faceNormals = new Float64Array(faces * 3);
  const atPoint = new Map();
  const corners = [];

  for (let i = 0; i < vertices.length; i += 3) {
    const key = [vertices[i], vertices[i + 1], vertices[i + 2]].map((v) => v.toFixed(5)).join(",");
    if (!atPoint.has(key)) atPoint.set(key, []);
    corners.push(atPoint.get(key));
  }

  for (let face = 0; face < faces; face++) {
    const ids = [triangles[face * 3], triangles[face * 3 + 1], triangles[face * 3 + 2]];
    const a = ids[0] * 3;
    const b = ids[1] * 3;
    const c = ids[2] * 3;
    const ux = vertices[b] - vertices[a];
    const uy = vertices[b + 1] - vertices[a + 1];
    const uz = vertices[b + 2] - vertices[a + 2];
    const vx = vertices[c] - vertices[a];
    const vy = vertices[c + 1] - vertices[a + 1];
    const vz = vertices[c + 2] - vertices[a + 2];
    const normal = [uy * vz - uz * vy, uz * vx - ux * vz, ux * vy - uy * vx];
    const length = Math.hypot(...normal) || 1;
    for (let k = 0; k < 3; k++) faceNormals[face * 3 + k] = normal[k] / length;

    for (let corner = 0; corner < 3; corner++) {
      const i = ids[corner] * 3;
      const j = ids[(corner + 1) % 3] * 3;
      const k = ids[(corner + 2) % 3] * 3;
      const u = [0, 1, 2].map((d) => vertices[j + d] - vertices[i + d]);
      const v = [0, 1, 2].map((d) => vertices[k + d] - vertices[i + d]);
      const cross = [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]];
      const angle = Math.atan2(
        Math.hypot(...cross),
        u.reduce((total, x, d) => total + x * v[d], 0),
      );
      corners[ids[corner]].push({ face, angle });
    }
  }

  const positions = new Float32Array(triangles.length * 3);
  const normals = new Float32Array(triangles.length * 3);
  const crease = Math.cos((creaseDegrees * Math.PI) / 180);
  for (let i = 0; i < triangles.length; i++) {
    const vertex = triangles[i];
    const face = Math.floor(i / 3);
    const sum = [0, 0, 0];
    for (const { face: other, angle } of corners[vertex]) {
      let facing = 0;
      for (let k = 0; k < 3; k++) facing += faceNormals[face * 3 + k] * faceNormals[other * 3 + k];
      if (facing + 1e-8 >= crease) for (let k = 0; k < 3; k++) sum[k] += faceNormals[other * 3 + k] * angle;
    }
    const length = Math.hypot(...sum) || 1;
    for (let k = 0; k < 3; k++) {
      positions[i * 3 + k] = vertices[vertex * 3 + k];
      normals[i * 3 + k] = sum[k] / length;
    }
  }
  return { positions, normals };
}

// ---- engine.js ----

// The badge itself: four lines of text and a stepped swatch, built as two watertight solids.
//
// A port of the toolbox CadQuery script (src/badge.py). The measurements are kept exactly: a rounded plate
// 56 x 30 x 3.2, a shallow recess that leaves a rim, four text labels, five thickness steps and a slot cut into
// the underside. Where CadQuery unioned everything into one solid, here the printed top layer — the rim and the
// text together — is its own solid, so in the 3MF the rim and the text share one filament and the body another,
// exactly as the original prints.
//
// Everything is parametric through GEOMETRY and DEFAULTS; leaving them alone reproduces badge.py to the
// millimetre. All the 2D work is Manifold's CrossSection: a rounded rectangle is a smaller rectangle grown
// outwards with a round join, and a glyph is its real outline with its counters.

// Measurements, millimetres, origin at the plate's centre, z = 0 the underside. Straight from badge.py.
export const GEOMETRY = {
  plateW: 56,
  plateH: 30,
  plateD: 3.2,
  plateFillet: 2.5,
  recessW: 54,
  recessH: 28,
  recessFillet: 1.5,
  recessZ: 2.7, // recess floor; the rim runs from here up to the plate top (3.2), so it is 0.5 high
  textSize: 6,
  // The glyphs sit ON the recess floor, the same 0.5 mm band as the rim (2.7 → 3.2), rather than reaching down
  // into the body. That way the body is one filament up to 2.7 and the rim and text the other above it, so the
  // print makes a single colour change instead of swapping back and forth through the embedded letters.
  textRise: 0.5, // extruded height of the glyphs
  textZ: 2.7, // text bottom, resting on the recess floor; the top lands at 3.2, flush with the rim
  step: 6,
  stepCount: 5,
  stepStartX: 22,
  stepY: -8.5,
  stepBase: 0.35, // remaining thickness under the first step
  stepRise: 0.5, // each step adds this to the remaining thickness
  bottomW: 39.2,
  bottomH: 9.5,
  bottomD: 1.8,
  bottomY: 4,
};

// The defaults a fresh window opens with, so it renders a real badge at once. width and textSize match badge.py.
export const DEFAULTS = {
  brand: "Bambu",
  type: "Matte",
  material: "PLA",
  color: "Black",
  temperature: 230,
  steps: true,
  width: GEOMETRY.plateW,
  textSize: GEOMETRY.textSize,
};

// Every linear measurement scales together with the plate width, so the whole badge grows or shrinks in proportion
// and the layout never breaks.
const SCALED = [
  "plateW",
  "plateH",
  "plateD",
  "plateFillet",
  "recessW",
  "recessH",
  "recessFillet",
  "recessZ",
  "textRise",
  "textZ",
  "step",
  "stepStartX",
  "stepY",
  "stepBase",
  "stepRise",
  "bottomW",
  "bottomH",
  "bottomD",
  "bottomY",
];

// Where each label sits and how it lines up, as in badge.py. The top line is brand and type together.
const LABELS = [
  { field: "heading", x: -25, y: 8.5, align: "left" },
  { field: "color", x: -25, y: 0, align: "left" },
  { field: "temperature", x: 25, y: 0, align: "right" },
  { field: "material", x: -25, y: -8.5, align: "left" },
];

function fail(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

/** A glyph path from opentype, flattened to polygons in millimetres, y up (opentype draws y down). */
function pathToPolygons(path, segments = 10) {
  const polygons = [];
  let current = null;
  let start = null;
  let from = null;
  const push = (x, y) => current.push([x, -y]);
  const quad = (p0, c, p1) => {
    for (let i = 1; i <= segments; i++) {
      const t = i / segments;
      const u = 1 - t;
      push(u * u * p0[0] + 2 * u * t * c[0] + t * t * p1[0], u * u * p0[1] + 2 * u * t * c[1] + t * t * p1[1]);
    }
  };
  const cubic = (p0, c1, c2, p1) => {
    for (let i = 1; i <= segments; i++) {
      const t = i / segments;
      const u = 1 - t;
      push(
        u * u * u * p0[0] + 3 * u * u * t * c1[0] + 3 * u * t * t * c2[0] + t * t * t * p1[0],
        u * u * u * p0[1] + 3 * u * u * t * c1[1] + 3 * u * t * t * c2[1] + t * t * t * p1[1],
      );
    }
  };
  for (const cmd of path.commands) {
    if (cmd.type === "M") {
      if (current && current.length > 2) polygons.push(current);
      current = [];
      start = [cmd.x, cmd.y];
      from = start;
      push(cmd.x, cmd.y);
    } else if (cmd.type === "L") {
      push(cmd.x, cmd.y);
      from = [cmd.x, cmd.y];
    } else if (cmd.type === "Q") {
      quad(from, [cmd.x1, cmd.y1], [cmd.x, cmd.y]);
      from = [cmd.x, cmd.y];
    } else if (cmd.type === "C") {
      cubic(from, [cmd.x1, cmd.y1], [cmd.x2, cmd.y2], [cmd.x, cmd.y]);
      from = [cmd.x, cmd.y];
    } else if (cmd.type === "Z") {
      if (current && current.length > 2) polygons.push(current);
      current = null;
      from = start;
    }
  }
  if (current && current.length > 2) polygons.push(current);
  return polygons;
}

function bounds(polygons) {
  const min = [Infinity, Infinity];
  const max = [-Infinity, -Infinity];
  for (const polygon of polygons)
    for (const [x, y] of polygon) {
      min[0] = Math.min(min[0], x);
      min[1] = Math.min(min[1], y);
      max[0] = Math.max(max[0], x);
      max[1] = Math.max(max[1], y);
    }
  return { min, max };
}

const shift = (polygons, dx, dy) => polygons.map((polygon) => polygon.map(([x, y]) => [x + dx, y + dy]));

/** One label's polygons, moved so its anchor lands on the target, centred vertically — the badge.py alignment. */
function placeLabel(font, text, size, { x, y, align }) {
  const polygons = pathToPolygons(font.getPath(text, 0, 0, size));
  if (!polygons.length) return [];
  const box = bounds(polygons);
  const anchorX = align === "right" ? box.max[0] : box.min[0];
  return shift(polygons, x - anchorX, y - (box.min[1] + box.max[1]) / 2);
}

/** The flat vertices (x, y, z triples) and triangles of a Manifold solid, from its mesh. */
function meshArrays(solid) {
  const mesh = solid.getMesh();
  const vertices = new Float32Array((mesh.vertProperties.length / mesh.numProp) * 3);
  for (let i = 0, v = 0; i < mesh.vertProperties.length; i += mesh.numProp, v += 3) {
    vertices[v] = mesh.vertProperties[i];
    vertices[v + 1] = mesh.vertProperties[i + 1];
    vertices[v + 2] = mesh.vertProperties[i + 2];
  }
  return { vertices, triangles: new Uint32Array(mesh.triVerts) };
}

/**
 * Builds the badge. `api` is Manifold's `{ CrossSection, Manifold }`, `font` an opentype font, `input` the fields
 * and any geometry overrides. Returns the body and the rim-and-text as separate solids with their meshes, named so
 * the 3MF assigns each its own filament, and the overall size.
 */
export function buildBadge(api, font, input = {}) {
  const { CrossSection: C, Manifold: M } = api;
  const s = { ...DEFAULTS, ...input };
  const g = { ...GEOMETRY, ...(input.geometry ?? {}) };
  const scale = Math.max(0.3, (Number(s.width) || GEOMETRY.plateW) / GEOMETRY.plateW);
  for (const key of SCALED) g[key] *= scale;
  g.textSize = Math.max(1, Number(s.textSize) || GEOMETRY.textSize * scale);
  const labels = LABELS.map((label) => ({ ...label, x: label.x * scale, y: label.y * scale }));
  const heading = [String(s.brand ?? "").trim(), String(s.type ?? "").trim()].filter(Boolean).join(" ");
  const values = {
    heading,
    material: String(s.material ?? "")
      .trim()
      .toUpperCase(),
    color: String(s.color ?? "")
      .trim()
      .toLowerCase(),
    temperature: `${Math.round(Number(s.temperature) || 0)}\u00b0C`,
  };

  const rubbish = [];
  const keep = (x) => (rubbish.push(x), x);

  try {
    const roundedRect = (w, h, r) => {
      const base = keep(C.square([Math.max(0.01, w - 2 * r), Math.max(0.01, h - 2 * r)], true));
      return r > 0 ? keep(base.offset(r, "Round", 2, 64)) : base;
    };

    const plateSection = roundedRect(g.plateW, g.plateH, g.plateFillet);
    const recessSection = roundedRect(g.recessW, g.recessH, g.recessFillet);

    // The body is a clean slab up to the recess floor (z = 2.7); the raised rim and the text form the top 0.5 mm
    // layer above it. Building the body this way — rather than sinking a recess into a full-height plate — leaves no
    // numerical sliver at the recess edge, and keeps the body a single colour up to one height.
    const rimHeight = g.plateD - g.recessZ;
    const rim = keep(keep(keep(plateSection.subtract(recessSection)).extrude(rimHeight)).translate([0, 0, g.recessZ]));

    let plate = keep(plateSection.extrude(g.recessZ));

    // Five thickness steps: each box leaves the material below its underside standing.
    if (s.steps) {
      for (let i = 0; i < g.stepCount; i++) {
        const dz = g.stepBase + i * g.stepRise;
        const cut = keep(
          keep(M.cube([g.step, g.step, g.step], false)).translate([
            g.stepStartX - i * g.step - g.step / 2,
            g.stepY - g.step / 2,
            dz,
          ]),
        );
        plate = keep(plate.subtract(cut));
      }
    }

    // Slot on the underside.
    plate = keep(
      plate.subtract(
        keep(
          keep(M.cube([g.bottomW, g.bottomH, g.bottomD], false)).translate([
            -g.bottomW / 2,
            g.bottomY - g.bottomH / 2,
            0,
          ]),
        ),
      ),
    );

    // Text as one solid, each label placed as in the original (positions scaled with the plate).
    const labelPolys = [];
    for (const label of labels) {
      const text = values[label.field];
      if (text) labelPolys.push(...placeLabel(font, text, g.textSize, label));
    }

    let top = rim;
    if (labelPolys.length) {
      const section = keep(new C(labelPolys, "EvenOdd"));
      if (!section.isEmpty()) {
        // The letters rest on the recess floor (z = 2.7) rather than reaching into the body, so the rim and the
        // text form one 0.5 mm top layer in the second filament and the print changes colour only once.
        const textSolid = keep(keep(section.extrude(g.textRise)).translate([0, 0, g.textZ]));
        top = keep(M.union([rim, textSolid]));
      }
    }

    if (plate.volume() < 1) throw fail("empty", "The plate came out empty.");

    const models = [
      { name: "plate", slot: 0, ...meshArrays(plate) },
      { name: "rim-and-text", slot: 1, ...meshArrays(top) },
    ];

    const min = [Infinity, Infinity, Infinity];
    const max = [-Infinity, -Infinity, -Infinity];
    for (const model of models)
      for (let i = 0; i < model.vertices.length; i += 3)
        for (let k = 0; k < 3; k++) {
          min[k] = Math.min(min[k], model.vertices[i + k]);
          max[k] = Math.max(max[k], model.vertices[i + k]);
        }

    return {
      models,
      size: max.map((v, i) => v - min[i]),
      bounds: { min, max },
      manifold: models.every((model) => model.triangles.length > 0),
    };
  } finally {
    for (const object of new Set(rubbish.reverse())) {
      try {
        object.delete();
      } catch {
        // already freed
      }
    }
  }
}

/** The download name: `{brand}_{type}_{material}_{color}_badge.<ext>`, lowercased, spaces to underscores. */
export function badgeFileName(input, extension = "3mf") {
  const part = (value) =>
    String(value ?? "")
      .trim()
      .toLowerCase()
      .replace(/\s+/g, "_");
  const stem = [input.brand, input.type, input.material, input.color].map(part).filter(Boolean).join("_");
  return `${stem || "filament"}_badge.${extension}`;
}

// ---- files.js ----

// The badge as files.
//
// The 3MF keeps the plate and the text as two objects in one assembly, with a colour list and a Bambu-style
// settings part naming the extruder for each — so a slicer opens it already told apart and assigned, ready to
// print in two colours. No printer profile and no G-code go in: those belong to the person slicing it.

const utf8 = new TextEncoder();

let crcTable = null;
function crc32(bytes) {
  if (!crcTable) {
    crcTable = new Uint32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      crcTable[n] = c >>> 0;
    }
  }
  let crc = 0xffffffff;
  for (let i = 0; i < bytes.length; i++) crc = crcTable[(crc ^ bytes[i]) & 0xff] ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}

const deflate = async (bytes) => {
  const stream = new Blob([bytes]).stream().pipeThrough(new CompressionStream("deflate-raw"));
  return new Uint8Array(await new Response(stream).arrayBuffer());
};

/** A ZIP of the entries given, each squeezed where squeezing helps. */
async function zip(entries) {
  const chunks = [];
  const directory = [];
  let offset = 0;
  for (const [name, text] of entries) {
    const nameBytes = utf8.encode(name);
    const raw = utf8.encode(text);
    const crc = crc32(raw);
    const packed = await deflate(raw);
    const squeezed = packed.length < raw.length;
    const data = squeezed ? packed : raw;

    const local = new Uint8Array(30);
    const view = new DataView(local.buffer);
    view.setUint32(0, 0x04034b50, true);
    view.setUint16(4, 20, true);
    view.setUint16(8, squeezed ? 8 : 0, true);
    view.setUint32(14, crc, true);
    view.setUint32(18, data.length, true);
    view.setUint32(22, raw.length, true);
    view.setUint16(26, nameBytes.length, true);
    chunks.push(local, nameBytes, data);

    const central = new Uint8Array(46);
    const centralView = new DataView(central.buffer);
    centralView.setUint32(0, 0x02014b50, true);
    centralView.setUint16(4, 20, true);
    centralView.setUint16(6, 20, true);
    centralView.setUint16(10, squeezed ? 8 : 0, true);
    centralView.setUint32(16, crc, true);
    centralView.setUint32(20, data.length, true);
    centralView.setUint32(24, raw.length, true);
    centralView.setUint16(28, nameBytes.length, true);
    centralView.setUint32(42, offset, true);
    directory.push(central, nameBytes);
    offset += local.length + nameBytes.length + data.length;
  }
  const directorySize = directory.reduce((total, part) => total + part.length, 0);
  const end = new Uint8Array(22);
  const endView = new DataView(end.buffer);
  endView.setUint32(0, 0x06054b50, true);
  endView.setUint16(8, entries.length, true);
  endView.setUint16(10, entries.length, true);
  endView.setUint32(12, directorySize, true);
  endView.setUint32(16, offset, true);

  const all = [...chunks, ...directory, end];
  const out = new Uint8Array(all.reduce((total, part) => total + part.length, 0));
  let at = 0;
  for (const part of all) {
    out.set(part, at);
    at += part.length;
  }
  return out;
}

const xml = (value) =>
  String(value).replace(
    /[&<>"']/g,
    (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&apos;" })[c],
  );

const DEFAULT_COLOURS = ["#2E3440", "#E5E9F0"];

/** The badge as a 3MF: one assembly, the plate and the text as parts, each with its colour and its extruder. */
export async function threeMf(models, colours = DEFAULT_COLOURS, { title = "Filament badge" } = {}) {
  const identity = "1 0 0 0 1 0 0 0 1 0 0 0";
  const assembly = 100;
  const highest = models.reduce((top, model) => Math.max(top, model.slot ?? 0), 0);
  const colourList = Array.from({ length: highest + 1 }, (_, i) => colours[i] ?? DEFAULT_COLOURS[i] ?? "#808080");

  const parts = models.map((model, i) => {
    const slot = model.slot ?? 0;
    const name = `${model.name} [${slot + 1}]`;
    let vertices = "";
    let triangles = "";
    for (let j = 0; j < model.vertices.length; j += 3) {
      vertices += `<vertex x="${model.vertices[j].toFixed(5)}" y="${model.vertices[j + 1].toFixed(5)}" z="${model.vertices[j + 2].toFixed(5)}"/>`;
    }
    for (let j = 0; j < model.triangles.length; j += 3) {
      triangles += `<triangle v1="${model.triangles[j]}" v2="${model.triangles[j + 1]}" v3="${model.triangles[j + 2]}"/>`;
    }
    return {
      id: i + 1,
      slot,
      name,
      mesh:
        `<object id="${i + 1}" type="model" name="${xml(name)}" pid="${1000 + slot}" pindex="0">` +
        `<mesh><vertices>${vertices}</vertices><triangles>${triangles}</triangles></mesh></object>`,
    };
  });

  const groups = colourList
    .map(
      (colour, i) =>
        `<m:colorgroup id="${1000 + i}"><m:color color="${colour.replace("#", "").toUpperCase()}FF"/></m:colorgroup>`,
    )
    .join("");
  const model =
    `<?xml version="1.0" encoding="UTF-8"?>` +
    `<model unit="millimeter" xml:lang="en-US" xmlns="http://schemas.microsoft.com/3dmanufacturing/core/2015/02" ` +
    `xmlns:m="http://schemas.microsoft.com/3dmanufacturing/material/2015/02">` +
    `<metadata name="Title">${xml(title)}</metadata>` +
    `<metadata name="Application">Thingport filament badge generator</metadata>` +
    `<resources>${groups}${parts.map((p) => p.mesh).join("")}` +
    `<object id="${assembly}" type="model" name="${xml(title)}"><components>` +
    parts.map((p) => `<component objectid="${p.id}" transform="${identity}"/>`).join("") +
    `</components></object></resources>` +
    `<build><item objectid="${assembly}" transform="${identity}"/></build></model>`;

  const settings =
    `<?xml version="1.0" encoding="UTF-8"?><config><object id="${assembly}">` +
    `<metadata key="name" value="${xml(title)}"/><metadata key="extruder" value="1"/>` +
    parts
      .map(
        (p) =>
          `<part id="${p.id}" subtype="normal_part"><metadata key="name" value="${xml(p.name)}"/>` +
          `<metadata key="extruder" value="${p.slot + 1}"/></part>`,
      )
      .join("") +
    `</object></config>`;

  return zip([
    [
      "[Content_Types].xml",
      `<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">` +
        `<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>` +
        `<Default Extension="model" ContentType="application/vnd.ms-package.3dmanufacturing-3dmodel+xml"/>` +
        `<Default Extension="config" ContentType="application/xml"/></Types>`,
    ],
    [
      "_rels/.rels",
      `<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">` +
        `<Relationship Target="/3D/3dmodel.model" Id="rel0" Type="http://schemas.microsoft.com/3dmanufacturing/2013/01/3dmodel"/></Relationships>`,
    ],
    ["3D/3dmodel.model", model],
    ["Metadata/model_settings.config", settings],
  ]);
}

/** The whole badge in one binary STL, for anything that reads nothing else. STL carries no colours. */
export function stl(models, { title = "Filament badge" } = {}) {
  const count = models.reduce((total, model) => total + model.triangles.length / 3, 0);
  const bytes = new Uint8Array(84 + count * 50);
  const view = new DataView(bytes.buffer);
  utf8.encodeInto(`${title} - Thingport filament badge generator`.slice(0, 79), bytes.subarray(0, 80));
  view.setUint32(80, count, true);
  let at = 84;
  for (const model of models) {
    const point = (index) => [model.vertices[index * 3], model.vertices[index * 3 + 1], model.vertices[index * 3 + 2]];
    for (let j = 0; j < model.triangles.length; j += 3) {
      const a = point(model.triangles[j]);
      const b = point(model.triangles[j + 1]);
      const c = point(model.triangles[j + 2]);
      const ux = b[0] - a[0];
      const uy = b[1] - a[1];
      const uz = b[2] - a[2];
      const vx = c[0] - a[0];
      const vy = c[1] - a[1];
      const vz = c[2] - a[2];
      let nx = uy * vz - uz * vy;
      let ny = uz * vx - ux * vz;
      let nz = ux * vy - uy * vx;
      const length = Math.hypot(nx, ny, nz) || 1;
      nx /= length;
      ny /= length;
      nz /= length;
      for (const value of [nx, ny, nz, ...a, ...b, ...c]) {
        view.setFloat32(at, value, true);
        at += 4;
      }
      at += 2;
    }
  }
  return bytes;
}

// ---- viewer.js ----

// The badge in three dimensions, drawn with Thingport's own Three.js.
//
// The plate and the text are each their own mesh in their own colour, so a two-colour badge looks here the way it
// comes off the printer. It draws when something changes rather than every frame, so a still window costs nothing.


const HOME = { around: -60, up: 32, zoom: 1 };

/**
 * A viewer on one canvas. `three` is what `library("three")` gives. Returns null where the browser has no WebGL,
 * and the window then shows the figures without a picture.
 */
export function createViewer(three, canvas) {
  let renderer;
  try {
    renderer = new three.WebGLRenderer({ canvas, antialias: true, alpha: true, preserveDrawingBuffer: true });
  } catch {
    return null;
  }
  renderer.setClearColor(0x000000, 0);

  const scene = new three.Scene();
  const camera = new three.PerspectiveCamera(36, 1, 0.1, 5000);
  const key = new three.DirectionalLight(0xffffff, 2.2);
  key.position.set(-0.4, -0.9, 1.1);
  const rim = new three.DirectionalLight(0xffffff, 0.7);
  rim.position.set(0.8, 0.6, 0.4);
  scene.add(key, rim, new three.AmbientLight(0xffffff, 1.1), new three.HemisphereLight(0xffffff, 0x404458, 1.2));

  const group = new three.Group();
  scene.add(group);

  const orbit = { ...HOME };
  const centre = new three.Vector3();
  let radius = 30;
  let frame = 0;
  let disposed = false;

  function place() {
    const upright = (camera.fov * Math.PI) / 180;
    const across = 2 * Math.atan(Math.tan(upright / 2) * Math.max(0.2, camera.aspect));
    const distance = (radius * 1.1) / Math.sin(Math.min(upright, across) / 2) / Math.max(0.15, orbit.zoom);
    const around = (orbit.around * Math.PI) / 180;
    const up = (orbit.up * Math.PI) / 180;
    camera.position.set(
      centre.x + distance * Math.cos(up) * Math.cos(around),
      centre.y + distance * Math.cos(up) * Math.sin(around),
      centre.z + distance * Math.sin(up),
    );
    camera.up.set(0, 0, 1);
    camera.lookAt(centre);
    camera.near = Math.max(0.1, distance - radius * 4);
    camera.far = distance + radius * 6;
    camera.updateProjectionMatrix();
  }

  function draw() {
    const ratio = Math.min(devicePixelRatio || 1, 2);
    const width = Math.max(1, canvas.clientWidth);
    const height = Math.max(1, canvas.clientHeight);
    renderer.setPixelRatio(ratio);
    if (
      renderer.domElement.width !== Math.round(width * ratio) ||
      renderer.domElement.height !== Math.round(height * ratio)
    ) {
      renderer.setSize(width, height, false);
    }
    camera.aspect = width / height;
    place();
    renderer.render(scene, camera);
  }

  const redraw = () => {
    if (frame || disposed) return;
    frame = requestAnimationFrame(() => {
      frame = 0;
      draw();
    });
  };
  const turn = (around, up) => {
    orbit.around = (orbit.around + around) % 360;
    orbit.up = Math.max(-89.9, Math.min(89.9, orbit.up + up));
    redraw();
  };
  const zoom = (factor) => {
    orbit.zoom = Math.max(0.15, Math.min(10, orbit.zoom * factor));
    redraw();
  };

  let last = null;
  const down = (event) => {
    if (event.button !== 0) return;
    canvas.setPointerCapture(event.pointerId);
    last = { x: event.clientX, y: event.clientY };
    canvas.style.cursor = "grabbing";
  };
  const move = (event) => {
    if (!last) return;
    turn(-(event.clientX - last.x) * 0.5, (event.clientY - last.y) * 0.4);
    last = { x: event.clientX, y: event.clientY };
  };
  const up = () => {
    last = null;
    canvas.style.cursor = "";
  };
  const wheel = (event) => {
    event.preventDefault();
    zoom(event.deltaY > 0 ? 1 / 1.12 : 1.12);
  };
  const listeners = [
    ["pointerdown", down],
    ["pointermove", move],
    ["pointerup", up],
    ["pointercancel", up],
  ];
  for (const [type, fn] of listeners) canvas.addEventListener(type, fn);
  canvas.addEventListener("wheel", wheel, { passive: false });
  const resize = new ResizeObserver(redraw);
  resize.observe(canvas);

  const empty = () => {
    for (const child of [...group.children]) {
      group.remove(child);
      child.geometry?.dispose?.();
      child.material?.dispose?.();
    }
  };

  const build = (model) => {
    const { positions, normals } = creasedGeometry(model.vertices, model.triangles);
    const geometry = new three.BufferGeometry();
    geometry.setAttribute("position", new three.BufferAttribute(positions, 3));
    geometry.setAttribute("normal", new three.BufferAttribute(normals, 3));
    return geometry;
  };

  const shade = (colour) =>
    new three.MeshStandardMaterial({ color: new three.Color(colour), roughness: 0.62, metalness: 0.02 });

  return {
    /** Shows the engine's solids. `colourOf(model)` gives each one its colour; `fit` recentres the camera. */
    show(models, { colourOf, fit = true } = {}) {
      empty();
      const box = new three.Box3();
      for (const model of models) {
        const geometry = build(model);
        const mesh = new three.Mesh(geometry, shade(colourOf?.(model) ?? "#b9c2cf"));
        group.add(mesh);
        geometry.computeBoundingBox();
        box.union(geometry.boundingBox);
      }
      if (!box.isEmpty() && fit) {
        box.getCenter(centre);
        radius = Math.max(6, box.getSize(new three.Vector3()).length() / 2);
      }
      redraw();
    },
    clear() {
      empty();
      redraw();
    },
    redraw,
    /** The canvas as a picture, for the cover of a saved model. */
    toBlob: (type = "image/png") =>
      new Promise((resolve) => {
        draw();
        canvas.toBlob(resolve, type);
      }),
    dispose() {
      disposed = true;
      cancelAnimationFrame(frame);
      resize.disconnect();
      for (const [type, fn] of listeners) canvas.removeEventListener(type, fn);
      canvas.removeEventListener("wheel", wheel);
      empty();
      renderer.dispose();
    },
  };
}

// ---- ui.js ----

// The window: the form, the live preview, and the two ways out — a download or a model in the library.
//
// Building the badge is a few milliseconds, so the preview is rebuilt as the user types, debounced, and the window
// opens on a finished badge from the defaults. A failure is shown in a toast and never leaves a button stuck,
// which is the bug the original badge.py guarded against.


// The default typeface: Arimo Bold is metric-compatible with Arial, so it matches the original badge.py exactly.
const ARIMO_ID = "__arimo-bold";

/** @param {import("../thingport").ToolSdk} thingport */
export default async function mount(thingport) {
  const { root, storage, models, collections, ui, t, labels, theme } = thingport;
  labels();

  const $ = (selector) => root.querySelector(selector);

  // The tool's own CSS variables, from Thingport's theme, so the window matches the rest of the app in either theme.
  const shell = $(".fbg") ?? root;
  const themeVars = {
    bg: theme.background,
    panel: theme.paper,
    divider: theme.divider,
    text: theme.text,
    muted: theme.textSecondary,
    accent: theme.primary,
    "accent-ink": theme.primaryContrast ?? "#ffffff",
    danger: theme.error,
    font: theme.fontFamily,
  };
  for (const [name, value] of Object.entries(themeVars)) shell.style.setProperty(`--${name}`, value);

  const brand = $(".fbg-brand");
  const type = $(".fbg-type");
  const material = $(".fbg-material");
  const colour = $(".fbg-color");
  const width = $(".fbg-width");
  const temperature = $(".fbg-temp");
  const textSize = $(".fbg-textsize");
  const steps = $(".fbg-steps");
  const fontSelect = $(".fbg-font");
  const plateColour = $(".fbg-plate-colour");
  const textColour = $(".fbg-text-colour");
  const downloadButton = $(".fbg-download");
  const saveButton = $(".fbg-save");
  const status = $(".fbg-status");
  const sizeOut = $(".fbg-size");
  const canvas = $(".fbg-canvas");

  const read = () => ({
    brand: brand.value,
    type: type.value,
    material: material.value,
    color: colour.value,
    width: Math.min(160, Math.max(24, Number(width.value) || DEFAULTS.width)),
    temperature: Math.min(350, Math.max(150, Number(temperature.value) || 230)),
    textSize: Math.min(16, Math.max(2, Number(textSize.value) || DEFAULTS.textSize)),
    steps: steps.checked,
  });
  const ready = () => Boolean(brand.value.trim() && material.value.trim() && colour.value.trim());

  const [{ CrossSection, Manifold }, fonts, opentype] = await Promise.all([
    thingport.library("manifold"),
    thingport.library("fonts"),
    thingport.library("opentype"),
  ]);
  const api = { CrossSection, Manifold };

  // Arimo Bold, bundled with the tool, comes first and is the default — it is metric-compatible with Arial, so the
  // badge matches the original. Every Thingport font follows it, loaded only when picked.
  const arimo = opentype.parse(arimoBoldBytes());
  const loadFont = (id) => (id === ARIMO_ID ? Promise.resolve(arimo) : fonts.load(id));
  const addOption = (value, label) => {
    const option = document.createElement("option");
    option.value = value;
    option.textContent = label;
    fontSelect.append(option);
  };
  addOption(ARIMO_ID, t("font.arimo"));
  for (const font of fonts.list) addOption(font.id, font.name);
  const isKnownFont = (id) => id === ARIMO_ID || fonts.list.some((f) => f.id === id);

  const stored = (await storage.get("last")) ?? {};
  brand.value = stored.brand ?? DEFAULTS.brand;
  type.value = stored.type ?? DEFAULTS.type;
  material.value = stored.material ?? DEFAULTS.material;
  colour.value = stored.color ?? DEFAULTS.color;
  width.value = String(stored.width ?? DEFAULTS.width);
  temperature.value = String(stored.temperature ?? DEFAULTS.temperature);
  textSize.value = String(stored.textSize ?? DEFAULTS.textSize);
  steps.checked = stored.steps ?? DEFAULTS.steps;
  fontSelect.value = isKnownFont(stored.fontId) ? stored.fontId : ARIMO_ID;
  plateColour.value = stored.plateColour ?? "#2E3440";
  textColour.value = stored.textColour ?? "#E5E9F0";

  let font = await loadFont(fontSelect.value);
  const viewer = createViewer(await thingport.library("three"), canvas);
  if (!viewer) $(".fbg-stage").classList.add("fbg-no-webgl");

  let latest = null;
  const colourOf = (model) => (model.slot === 1 ? textColour.value : plateColour.value);

  const rebuild = (fit = false) => {
    let result;
    try {
      result = buildBadge(api, font, read());
    } catch (error) {
      latest = null;
      status.textContent = t("buildFailed", { reason: error.message });
      viewer?.clear();
      updateButtons();
      return;
    }
    latest = result;
    viewer?.show(result.models, { colourOf, fit });
    const [w, d, h] = result.size.map((value) => value.toFixed(1));
    sizeOut.textContent = t("size", { w, d, h });
    status.textContent = ready() ? t("ready") : t("need");
    updateButtons();
  };

  function updateButtons() {
    const can = Boolean(latest) && ready();
    downloadButton.disabled = !can;
    saveButton.disabled = !can;
  }

  const persist = () =>
    storage.set("last", {
      ...read(),
      fontId: fontSelect.value,
      plateColour: plateColour.value,
      textColour: textColour.value,
    });

  let timer = 0;
  const debounced = () => {
    clearTimeout(timer);
    timer = setTimeout(() => {
      rebuild(false);
      void persist();
    }, 180);
  };

  for (const field of [brand, type, material, colour, temperature, textSize])
    field.addEventListener("input", debounced);
  // Resizing the badge scales the default text with it, so the layout stays in proportion; the user can still
  // override the text size afterwards.
  width.addEventListener("input", () => {
    const scale = Math.min(160, Math.max(24, Number(width.value) || DEFAULTS.width)) / DEFAULTS.width;
    textSize.value = String(Math.round(DEFAULTS.textSize * scale * 2) / 2);
    debounced();
  });
  steps.addEventListener("change", () => {
    rebuild(false);
    void persist();
  });
  for (const picker of [plateColour, textColour])
    picker.addEventListener("input", () => {
      if (latest) viewer?.show(latest.models, { colourOf, fit: false });
      void persist();
    });
  fontSelect.addEventListener("change", async () => {
    font = await loadFont(fontSelect.value);
    rebuild(false);
    void persist();
  });

  const title = () => {
    const name = [brand.value.trim(), type.value.trim()].filter(Boolean).join(" ");
    return colour.value.trim() ? `${name} \u2013 ${colour.value.trim()}` : name || t("name");
  };

  downloadButton.addEventListener("click", async () => {
    if (!latest || !ready()) return;
    downloadButton.disabled = true;
    try {
      const data = await threeMf(latest.models, [plateColour.value, textColour.value], { title: title() });
      const name = badgeFileName(read(), "3mf");
      thingport.download({ name, data });
      ui.toast(t("downloaded", { name }), "success");
    } catch (error) {
      ui.toast(t("buildFailed", { reason: error.message }), "error");
    } finally {
      updateButtons();
    }
  });

  saveButton.addEventListener("click", async () => {
    if (!latest || !ready()) return;
    saveButton.disabled = true;
    const label = saveButton.textContent;
    saveButton.textContent = t("saving");
    try {
      const collection = await collections.pick({ title: t("saveWhere") });
      if (!collection) return;
      const data = await threeMf(latest.models, [plateColour.value, textColour.value], { title: title() });
      const model = await models.create({
        name: title(),
        description: t("madeBy"),
        tags: ["filament", "swatch", material.value.trim().toLowerCase()].filter(Boolean),
        collectionId: collection.id,
        files: [{ name: badgeFileName(read(), "3mf"), data }],
      });
      const cover = await viewer?.toBlob("image/png");
      if (cover) {
        try {
          await models.addImages(model.id, [{ name: "preview.png", data: cover, type: "image/png" }]);
        } catch {
          // a missing cover is not worth failing the save over
        }
      }
      ui.toast(t("saved", { name: model.name }), "success", { openModel: model.id });
    } catch (error) {
      ui.toast(t("saveFailed", { reason: error.message }), "error");
    } finally {
      saveButton.textContent = label;
      updateButtons();
    }
  });

  rebuild(true);

  return () => {
    clearTimeout(timer);
    viewer?.dispose();
  };
}
